mapper.select:
SELECT COUNT(1)                    AS totalItems,
       COALESCE(SUM(quantity), 0)  AS totalQuantity
FROM ck_shop_cart_item
WHERE del_flag = 0
  AND user_id = #{userId}
  AND store_id = #{storeId}

SELECT COUNT(1) FROM ck_shop_cart_item WHERE del_flag = 0
AND 1 = 0
AND store_id IN #{sid}

